from fastapi import FastAPI
from pydantic import BaseModel
from typing import List

app = FastAPI()

class State(BaseModel):
    id: int
    name: str
    verified: bool

class StateVerification(BaseModel):
    id: int
    state_id: int
    verified: bool
    reason: str

states = [
    State(id=1, name="NY", verified=True),
    State(id=2, name="CA", verified=True),
    State(id=3, name="TX", verified=True),
]

state_verifications = [
    StateVerification(id=1, state_id=1, verified=True, reason="Passed initial checks"),
    StateVerification(id=2, state_id=2, verified=True, reason="Passed initial checks"),
    StateVerification(id=3, state_id=3, verified=True, reason="Passed initial checks"),
]

@app.get("/states")
async def get_states():
    return states

@app.post("/verify-state")
async def verify_state(state_verification: StateVerification):
    state_verifications.append(state_verification)
    return {"message": "State verification added"}

@app.get("/state-verifications")
async def get_state_verifications():
    return state_verifications

@app.put("/update-state-verification")
async def update_state_verification(state_verification: StateVerification):
    for verification in state_verifications:
        if verification.id == state_verification.id:
            verification.verified = state_verification.verified
            verification.reason = state_verification.reason
            return {"message": "State verification updated"}
    return {"message": "State verification not found"}

@app.delete("/delete-state-verification")
async def delete_state_verification(state_verification_id: int):
    for i, verification in enumerate(state_verifications):
        if verification.id == state_verification_id:
            del state_verifications[i]
            return {"message": "State verification deleted"}
    return {"message": "State verification not found"}

from fastapi import FastAPI
from pydantic import BaseModel
from typing import List

app = FastAPI()

class State(BaseModel):
    id: int
    name: str
    verified: bool

class StateUpdate(BaseModel):
    id: int
    verified: bool

states = [
    State(id=1, name="NY", verified=False),
    State(id=2, name="CA", verified=False),
    State(id=3, name="TX", verified=False),
]

@app.post("/verify_state")
async def verify_state(state: StateUpdate):
    for s in states:
        if s.id == state.id:
            s.verified = state.verified
            return s
    return {"error": "State not found"}

@app.get("/states")
async def get_states():
    return states
